// Generated by `manage.py bazis_front screens` from spec/screens/task-card.yaml:
// never edit it, change the specs and generate it again.

import { useNavigate, useParams } from 'react-router';

import { useLanguage } from '@/bazis/i18n';
import { Screen } from '@/bazis/ui/app-shell';
import { permitted } from '@/bazis/ui/resource';
import { RelatedList, ResourceCard } from '@/bazis/ui/resource-card';
import { useCustomAction, useDestroyCardAction } from '@/bazis/ui/screens';
import { StatusBadge } from '@/bazis/ui/status-badge';
import { StatusHistory } from '@/bazis/ui/status-history';
import { TransitBar } from '@/bazis/ui/transit-bar';

import { ENTITIES } from './entities';
import { routeTo } from './screens';

const TASK = ENTITIES.task;
const STEP = ENTITIES.step;

export function TaskCardScreen() {
  const { id = '' } = useParams();
  const { t } = useLanguage();
  const navigate = useNavigate();
  const deleteAction = useDestroyCardAction({
    id: 'delete',
    label: t('screens.task-card.actions.delete.label'),
    title: t('screens.task-card.actions.delete.title'),
    path: TASK.path,
    item: id,
    then: routeTo('task-list'),
  });
  const escalateAction = useCustomAction({
    id: 'escalate',
    label: t('screens.task-card.actions.escalate.label'),
    path: TASK.path,
    action: 'escalate',
    target: 'item',
    item: id,
    fields: ['priority'],
    description: t('screens.task-card.actions.escalate.description'),
    message: t('screens.task-card.actions.escalate.message'),
  });
  return (
    <Screen
      id="task-card"
      parent={{ screen: 'task-list', label: t('screens.task-list.title'), to: routeTo('task-list') }}
    >
      <ResourceCard
        path={TASK.path}
        id={id}
        sections={[
          { id: 'main', fields: ['title', 'status', 'assignee', 'watchers', 'attachment', 'priority', 'location'] },
          { id: 'report', title: t('screens.task-card.card.sections.report.title'), fields: ['report'] },
        ]}
        edit
        badge={(item) => <StatusBadge resource={item} />}
        tabs={[
          { id: 'details', title: t('screens.task-card.card.tabs.details.title'), sections: ['main', 'report'] },
          {
            id: 'steps',
            title: t('screens.task-card.card.tabs.steps.title'),
            content: (_, meta) => (
              <RelatedList
                path={STEP.path}
                entity="step"
                relation="task"
                item={id}
                itemPath={TASK.path}
                title={t('screens.task-card.card.related.steps.title')}
                columns={['title', 'dt_created']}
                icon={STEP.Icon}
                add={
                  permitted(meta, 'change')
                    ? { id: 'add-step', label: t('screens.task-card.card.related.steps.add.label'), fields: ['title'] }
                    : undefined
                }
              />
            ),
          },
          {
            id: 'history',
            title: t('screens.task-card.card.tabs.history.title'),
            content: (item) => <StatusHistory resource={item} />,
          },
        ]}
        actions={[deleteAction.action, escalateAction.action]}
      >
        <TransitBar
          path={TASK.path}
          id={id}
          transits={TASK.transits}
          onDone={(done) => {
            if (done === null) void navigate(routeTo('task-list'));
          }}
        />
      </ResourceCard>
      {deleteAction.confirm}
      {escalateAction.dialog}
    </Screen>
  );
}
